import { Component, Event, EventEmitter, Prop, h } from '@stencil/core';

@Component({
  tag: 'std-card-button',
  styleUrl: 'std-card-button.css',
  shadow: true
})
export class StdCardButton {
  @Prop() classes: string;
  @Prop() cardTitle: string;
  @Prop() src: string;
  @Prop() icon: string;
  @Prop() iconClasses: string;
  @Prop() image: boolean;
  @Prop() disabled: boolean;

  @Event() clickEvent: EventEmitter;

  onClick(event: Event) {
    if (this.disabled) {
      return;
    }

    this.clickEvent.emit(event);
  }

  render() {
    const disabledOpacity = `${this.disabled ? 'opacity-[.4]' : ''}`;
    const iconClassList = [`text-xl leading-none icon-${this.icon} ${disabledOpacity}`, this.iconClasses].join(' ').trim().replace(/\s+/g, ' ');
    // h-full
    const disabledClassList = this.disabled ? `bg-disabledselect` : `bg-white shadow-modal cursor-pointer`;
    const cardClasses = [`rounded-lg p-4 css-card-button ${disabledClassList}`, this.classes].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class={cardClasses} onClick={e => this.onClick(e)}>
        <button class={`flex flex-col gap-2 ${this.disabled ? 'cursor-default' : ''}`}>
          {this.icon && <i class={iconClassList} />}
          {this.image && <std-image src={this.src} class={`w-6 h-6 ${disabledOpacity}`} />}
          <span class={`css-text  ${this.disabled ? 'text-labeldisabled' : 'text-dark font-bold'} text-sm text-left`}>{this.cardTitle}</span>
        </button>
      </div>
    );
  }
}
